def get_closest_vowel(word):
    vowels = "aeiouAEIOU"
    n = len(word)

    # Traverse the word from the end to the beginning
    for i in range(n - 1, 0, -1):
        if word[i] in vowels:
            # Check for consonant before the vowel
            if i > 1 and word[i - 1] not in vowels:
                # Check for consonant after the vowel
                if word[i + 1] not in vowels if i + 1 < n else True:
                    return word[i]
    return ""

